// ============================================================================

struct ReactiveColorSchemeState {
    binding: waterui::Binding<waterui::theme::ColorScheme>,
}

struct ReactiveColorState {
    binding: waterui::Binding<ResolvedColor>,
}

struct ReactiveFontState {
    binding: waterui::Binding<ResolvedFont>,
}

struct ReactiveEdgeInsetsState {
    binding: waterui::Binding<waterui_layout::padding::EdgeInsets>,
}

#[inline]
fn reactive_state<'a, T>(state_ptr: jlong) -> &'a T {
    unsafe { crate::borrow_ffi(state_ptr as *const T) }
}

fn color_scheme_from_ordinal(ordinal: jint) -> waterui::theme::ColorScheme {
    match ordinal {
        0 => waterui::theme::ColorScheme::Light,
        1 => waterui::theme::ColorScheme::Dark,
        value => panic!("unknown color scheme ordinal: {value}"),
    }
}

fn resolved_color_from_argb(argb: jint) -> ResolvedColor {
    let a = ((argb as u32) >> 24) as u8;
    let r = ((argb as u32) >> 16) as u8;
    let g = ((argb as u32) >> 8) as u8;
    let b = (argb as u32) as u8;

    let srgb = waterui_graphics::color::Srgb::new_u8(r, g, b);
    let mut resolved = ResolvedColor::from_srgb(srgb);
    resolved.opacity = a as f32 / 255.0;
    resolved
}

fn font_weight_from_ordinal(weight: jint) -> FontWeight {
    match weight {
        0 => FontWeight::Thin,
        1 => FontWeight::UltraLight,
        2 => FontWeight::Light,
        3 => FontWeight::Normal,
        4 => FontWeight::Medium,
        5 => FontWeight::SemiBold,
        6 => FontWeight::Bold,
        7 => FontWeight::UltraBold,
        8 => FontWeight::Black,
        value => panic!("unknown font weight ordinal: {value}"),
    }
}

fn resolved_system_font(size: jfloat, weight: jint) -> ResolvedFont {
    ResolvedFont::new(size, font_weight_from_ordinal(weight))
}

